PASS1_SEG_TOKENS = int(os.environ.get("CC_PASS1_SEG_TOKENS", "6000"))
PASS2_SEG_TOKENS = int(os.environ.get("CC_PASS2_SEG_TOKENS", "6000"))
VIS_DIM = int(os.environ.get("CC_VIS_DIM", "512"))
