def _read_meta(checkpoint_dir):
    meta_path = os.path.join(checkpoint_dir, "multimodal_meta.json")
    if os.path.exists(meta_path):
        with open(meta_path, "r", encoding="utf-8") as f:
            return json.load(f)
    return {}


def load_checkpoint(checkpoint_dir, base_model, tokenizer):
    """Load text-only or ASR+CLIP cross-attn checkpoint correctly.

    The cross-attn checkpoints save three things that must be restored together:
    (1) tokenizer with <VIS_i> tokens, (2) PEFT adapter in shared_lora/,
    (3) qformer.pt plus multimodal_meta.json.  The previous release-search
    eval path forcibly disabled visuals; this loader keeps text-only behavior
    but enables qformer visual injection when fusion_mode != text_only.
    """
    meta = _read_meta(checkpoint_dir)
    fusion_mode = os.environ.get("CC_FUSION_MODE", meta.get("fusion_mode", FUSION_MODE))
    num_query_tokens = int(os.environ.get("CC_NUM_QUERY_TOKENS", meta.get("num_query_tokens", NUM_QUERY_TOKENS)))
    vis_dim = int(os.environ.get("CC_VIS_DIM", meta.get("vis_dim", VIS_DIM)))

    lora_path = os.path.join(checkpoint_dir, "shared_lora")
    if not os.path.exists(lora_path):
        lora_path = os.path.join(checkpoint_dir, "pass1_lora")
    if not os.path.exists(lora_path) and os.path.exists(os.path.join(checkpoint_dir, "adapter_config.json")):
        lora_path = checkpoint_dir

    if not os.path.exists(lora_path):
        raise FileNotFoundError(
            f"No LoRA adapter found in {checkpoint_dir}. "
            f"Expected shared_lora/, pass1_lora/, or adapter_config.json in checkpoint root."
        )

    from .models.model_builder import clone_base_model_for_adapter
    from .models.fast_multimodal_lm import FastMultiModalCausalLM
    from .models.qformer import SimpleQFormer

    llm = clone_base_model_for_adapter(
        base_model,
        tokenizer,
        gradient_checkpointing=False,
        use_4bit=False,
        use_8bit=False,
        attn_implementation=os.environ.get("CC_ATTN_IMPL", "sdpa"),
    )
    llm = PeftModel.from_pretrained(llm, lora_path)
    hidden = llm.get_input_embeddings().weight.shape[1]

    qformer = None
    vis_token_ids = []
    if fusion_mode == "text_only" or num_query_tokens <= 0:
        fusion_mode = "text_only"
        num_query_tokens = 0
        print("[BUILD] text_only mode: Q-Former disabled, no visual features")
    else:
        vis_tokens = [f"<VIS_{i}>" for i in range(num_query_tokens)]
        missing = [tok for tok in vis_tokens if tokenizer.convert_tokens_to_ids(tok) is None]
        # Some tokenizers return unk_token_id instead of None for missing; guard that too.
        unk = getattr(tokenizer, "unk_token_id", None)
        missing += [tok for tok in vis_tokens if tokenizer.convert_tokens_to_ids(tok) == unk and tok not in tokenizer.get_vocab()]
        missing = sorted(set(missing), key=vis_tokens.index)
        if missing:
            raise ValueError(
                f"Tokenizer is missing VIS tokens {missing}. Load tokenizer from the multimodal checkpoint "
                f"or set CC_CHECKPOINT_DIR to a checkpoint containing tokenizer files."
            )
        vis_token_ids = tokenizer.convert_tokens_to_ids(vis_tokens)
        qformer = SimpleQFormer(
            vis_dim=vis_dim,
            q_hidden=int(os.environ.get("CC_QFORMER_HIDDEN", "512")),
            llm_hidden=hidden,
            num_query_tokens=num_query_tokens,
            num_heads=int(os.environ.get("CC_QFORMER_HEADS", "8")),
            num_layers=int(os.environ.get("CC_QFORMER_LAYERS", "2")),
        )
        qformer_path = os.path.join(checkpoint_dir, "qformer.pt")
        if not os.path.exists(qformer_path):
            raise FileNotFoundError(f"fusion_mode={fusion_mode} requires {qformer_path}")
        state = torch.load(qformer_path, map_location="cpu")
        qformer.load_state_dict(state, strict=True)
        print(f"[BUILD] fusion_mode={fusion_mode}, num_query_tokens={num_query_tokens}, vis_dim={vis_dim}")
        print(f"[LOAD] Q-Former loaded from {qformer_path}")
        print(f"[TOKENIZER] vis_token_ids={vis_token_ids}")

    model = FastMultiModalCausalLM(
        llm=llm,
        qformer=qformer,
        vis_token_ids=vis_token_ids,
        use_quantization=False,
        fusion_mode=fusion_mode,
        llm_hidden=hidden,
        vis_hidden=vis_dim,
        num_query_tokens=num_query_tokens,
    )
    model.disable_visual = (fusion_mode == "text_only")
    # Expose resolved runtime config to main() without relying on globals.
    model.resolved_fusion_mode = fusion_mode
    model.resolved_num_query_tokens = num_query_tokens
    model.resolved_vis_dim = vis_dim
    print(f"[LOAD] LoRA adapter loaded from {lora_path}")

    return model, model

def main():
    forbid_gt = os.environ.get("CC_FORBID_GT_SEGMENTS", "0") == "1"
    validate_evaluation_usage(EVAL_SCOPE, EVAL_PROTOCOL, CAPTION_MATCHING, forbid_gt,
                              os.environ.get("CC_SEARCH_DEV_ONLY", "0") == "1",
                              TEST_TEXT_JSONL, TEST_GT_JSONL)
    seed = int(os.environ.get("CC_SEED", "42"))
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)
    device = "cuda" if torch.cuda.is_available() else "cpu"

    print("=" * 60)
    print("CausalChapter Evaluation")
    print(f"checkpoint={CHECKPOINT_DIR}")
    print(f"fusion_mode={FUSION_MODE}")
    print("=" * 60)

    # Tokenizer: multimodal checkpoints contain added <VIS_i> tokens; text-only
    # checkpoints are also safe to load from here. Fall back to BASE_MODEL.
    tokenizer_source = CHECKPOINT_DIR if os.path.exists(os.path.join(CHECKPOINT_DIR, "tokenizer_config.json")) else BASE_MODEL
    from .data.tokenizer_compat import tokenizer_compat_kwargs
    tokenizer = AutoTokenizer.from_pretrained(
        tokenizer_source, trust_remote_code=True, local_files_only=True,
        **tokenizer_compat_kwargs(tokenizer_source),
    )
    print(f"[TOKENIZER] loaded from {tokenizer_source} (vocab={len(tokenizer)})")
    if tokenizer.pad_token_id is None:
        tokenizer.pad_token = tokenizer.eos_token

    # Model
    model_pass1, model_pass2 = load_checkpoint(CHECKPOINT_DIR, BASE_MODEL, tokenizer)
    model_pass1 = model_pass1.to(device)
    model_pass2 = model_pass2.to(device)
    model_pass1.eval()
    model_pass2.eval()

    # Data
    resolved_vis_dim = getattr(model_pass1, "resolved_vis_dim", VIS_DIM)
    resolved_num_query_tokens = getattr(model_pass1, "resolved_num_query_tokens", NUM_QUERY_TOKENS)
    print(f"[VIS] cache_dir={VIS_CACHE_DIR_ENV}")
    vis_index = build_vis_index(VIS_CACHE_DIR_ENV)
    gt_eval_data = build_gt_eval_data(TEST_GT_JSONL, TEST_TEXT_JSONL) if EVAL_SCOPE in {"gt", "both"} else []
    if EVAL_PROTOCOL == "strict":
        pred_eval_data = build_strict_pred_eval_data(TEST_TEXT_JSONL, TEST_GT_JSONL, TEST_PRED_BOUNDARY,
                                                   os.environ.get("CC_CHAPTER_TIMES"))
        for item in pred_eval_data:
            item["caption_matching"] = CAPTION_MATCHING
        for item in gt_eval_data:
            item["evaluation_protocol"] = "strict"
            item["gt_events"] = [{"start": start, "end": end, "sentence": title}
                                 for (start, end), title in zip(item["times"], item["gt_titles"])]
    elif EVAL_PROTOCOL == "legacy":
        pred_eval_data = build_pred_eval_data(TEST_TEXT_JSONL, TEST_GT_JSONL, TEST_PRED_BOUNDARY)
    else:
        raise ValueError("CC_EVAL_PROTOCOL must be strict or legacy")
    if EVAL_LIMIT > 0:
        gt_eval_data = gt_eval_data[:EVAL_LIMIT]
        pred_eval_data = pred_eval_data[:EVAL_LIMIT]
        print(f"[EVAL_LIMIT] using first {EVAL_LIMIT} videos")

    # Retrieval
    retrieval_system = None
    if CAUSAL_MODE != "off":
        from .retrieval.kl_support_retriever import KLSupportRetriever
        retrieval_system = KLSupportRetriever(
            generation_model=model_pass2,
            tokenizer=tokenizer,
            device=device,
            near_size=RETRIEVAL_NEAR_SIZE,
            semantic_size=RETRIEVAL_SEMANTIC_SIZE,
            final_topk=CAUSAL_TOPK,
            intervention_tokens=RETRIEVAL_INTERVENTION_TOKENS,
            variant_microbatch=RETRIEVAL_VARIANT_MICROBATCH,
            vis_dim=resolved_vis_dim,
            vis_token_count=resolved_num_query_tokens,
            input_max_tokens=INPUT_MAX_TOKENS,
        )
        print(f"[CAUSAL] enabled mode=light near={RETRIEVAL_NEAR_SIZE} semantic={RETRIEVAL_SEMANTIC_SIZE} topk={CAUSAL_TOPK} intervention={RETRIEVAL_INTERVENTION_TOKENS} mb={RETRIEVAL_VARIANT_MICROBATCH}")

    gen_kwargs = {"repetition_penalty": GEN_REPETITION_PENALTY}
    if GEN_NUM_BEAMS > 1:
        gen_kwargs["num_beams"] = GEN_NUM_BEAMS
    if GEN_NO_REPEAT_NGRAM_SIZE is not None:
        gen_kwargs["no_repeat_ngram_size"] = int(GEN_NO_REPEAT_NGRAM_SIZE)
    if GEN_MAX_NEW_TOKENS is not None:
        gen_kwargs["max_new_tokens"] = int(GEN_MAX_NEW_TOKENS)
    print(f"[GEN] kwargs: {gen_kwargs}")

    cider_gt = meteor_gt = soda_gt = None
    cider_pred = meteor_pred = soda_pred = None
    os.makedirs(EVAL_SAVE_DIR, exist_ok=True)

    if EVAL_SCOPE in {"both", "gt"}:
        # ---- GT boundary evaluation ----
        print("\n" + "=" * 60)
        print("EVAL: Ground-Truth Boundaries (Oracle)")
        print("=" * 60)
        with torch.no_grad():
            cider_gt, meteor_gt, soda_gt = eval_model(
                model_pass1=model_pass1, model_pass2=model_pass2,
                tokenizer=tokenizer, eval_data=gt_eval_data, vis_index=vis_index,
                retrieval_system=retrieval_system,
                vis_dim=resolved_vis_dim, vis_token_count=resolved_num_query_tokens,
                topk=CAUSAL_TOPK,
                pass1_seg_tokens=PASS1_SEG_TOKENS,
                pass2_seg_tokens=PASS2_SEG_TOKENS,
                input_max_tokens=INPUT_MAX_TOKENS,
                use_fewshot=USE_FEWSHOT, fewshot_num=FEWSHOT_NUM,
                device=device, gen_kwargs=gen_kwargs,
                save_dir=EVAL_SAVE_DIR, boundary_type="gt",
            )
        print(f"[GT] CIDEr={cider_gt:.2f}, METEOR={meteor_gt:.2f}, SODA_c={soda_gt:.2f}")

    if EVAL_SCOPE in {"both", "pred"}:
        # ---- Pred boundary evaluation (E2E) ----
        print("\n" + "=" * 60)
        print("EVAL: Predicted Boundaries (End-to-End)")
        print("=" * 60)
        with torch.no_grad():
            cider_pred, meteor_pred, soda_pred = eval_model(
                model_pass1=model_pass1, model_pass2=model_pass2,
                tokenizer=tokenizer, eval_data=pred_eval_data, vis_index=vis_index,
                retrieval_system=retrieval_system,
                vis_dim=resolved_vis_dim, vis_token_count=resolved_num_query_tokens,
                topk=CAUSAL_TOPK,
                pass1_seg_tokens=PASS1_SEG_TOKENS,
                pass2_seg_tokens=PASS2_SEG_TOKENS,
                input_max_tokens=INPUT_MAX_TOKENS,
                use_fewshot=USE_FEWSHOT, fewshot_num=FEWSHOT_NUM,
                device=device, gen_kwargs=gen_kwargs,
                save_dir=EVAL_SAVE_DIR, boundary_type="pred",
            )
        print(f"[Pred] CIDEr={cider_pred:.2f}, METEOR={meteor_pred:.2f}, SODA_c={soda_pred:.2f}")

    if EVAL_SCOPE not in {"both", "gt", "pred"}:
        raise ValueError(f"Invalid EVAL_SCOPE={EVAL_SCOPE!r}; expected both|gt|pred")

    # ---- Summary ----
    print("\n" + "=" * 60)
    print("SUMMARY")
    print("=" * 60)
    if cider_gt is not None:
        print(f"  GT boundaries:    CIDEr={cider_gt:.2f}, METEOR={meteor_gt:.2f}, SODA_c={soda_gt:.2f}")
    else:
        print("  GT boundaries:    SKIPPED")
    if cider_pred is not None:
        print(f"  Pred boundaries:  CIDEr={cider_pred:.2f}, METEOR={meteor_pred:.2f}, SODA_c={soda_pred:.2f}")
    else:
        print("  Pred boundaries:  SKIPPED")

    # Target scores for reference
    print(f"\n  Target (pred):    CIDEr=104.59, METEOR=17.87, SODA_c=12.73")

    # Save summary
    summary = {
        "checkpoint": CHECKPOINT_DIR,
        "eval_scope": EVAL_SCOPE,
        "evaluation_protocol": EVAL_PROTOCOL,
        "caption_matching": CAPTION_MATCHING,
        "gt_segmentation_forbidden": forbid_gt,
        "text_input": TEST_TEXT_JSONL,
        "gt_boundary": None if cider_gt is None else {"CIDEr": round(cider_gt, 2), "METEOR": round(meteor_gt, 2), "SODA_c": round(soda_gt, 2)},
        "pred_boundary": None if cider_pred is None else {"CIDEr": round(cider_pred, 2), "METEOR": round(meteor_pred, 2), "SODA_c": round(soda_pred, 2)},
    }
    os.makedirs(EVAL_SAVE_DIR, exist_ok=True)
    with open(os.path.join(EVAL_SAVE_DIR, "eval_summary.json"), "w") as f:
        json.dump(summary, f, indent=2)
    print(f"\n[SAVE] eval_summary.json -> {CHECKPOINT_DIR}")


if __name__ == "__main__":
    main()
